import { MakeLogicType, kea, key, listeners, path, props } from 'kea'

import { SessionRecordingPlaylistLogicProps, sessionRecordingsPlaylistLogic } from './sessionRecordingsPlaylistLogic'

export interface ReplayCollectionViewLogicProps {
    shortId: string
    listProps: SessionRecordingPlaylistLogicProps
    mainListProps?: SessionRecordingPlaylistLogicProps
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface replayCollectionViewLogicMeta {
    key: string
}

export type replayCollectionViewLogicType = MakeLogicType<
    {},
    {},
    ReplayCollectionViewLogicProps,
    replayCollectionViewLogicMeta
>

export const replayCollectionViewLogic = kea<replayCollectionViewLogicType>([
    path((key) => ['scenes', 'session-recordings', 'playlist', 'replayCollectionViewLogic', key]),
    props({} as ReplayCollectionViewLogicProps),
    key((props) => props.shortId),
    listeners(({ props }) => ({
        [sessionRecordingsPlaylistLogic(props.listProps).actionTypes.setSelectedRecordingId]: ({
            id,
        }: {
            id: string | null
        }) => {
            if (id && props.mainListProps) {
                sessionRecordingsPlaylistLogic(props.mainListProps).actions.setSelectedRecordingId(id)
            }
        },
    })),
])
